package net.civeira.phylax.features.access.userwebauthncredential.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class AaguidVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property aaguid of user webauthn credential ")
  void test_aaguid_v_o_builder() {
    Assertions.assertFalse(AaguidVO.nullValue().getAaguid().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(AaguidVO.tryFrom(null).getAaguid().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", AaguidVO.from("one").getAaguid().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> AaguidVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", AaguidVO.from("one").toString());
  }
}
